-- Closed local-only extension. Install after exact V7 input; no public RPC/grants.
begin;
create schema identity_adoption_v8;
revoke all on schema identity_adoption_v8 from public;
create table identity_adoption_v8.operations(tournament_id uuid not null,actor_id uuid not null,operation_id uuid not null,request jsonb not null,response jsonb not null,primary key(tournament_id,actor_id,operation_id));
create table identity_adoption_v8.reviews(tournament_id uuid not null,roster_id uuid not null,subject_id uuid not null references identity_trial_v4.subjects(id),coverage text not null check(coverage in('complete','incomplete_reviewed')),actor_id uuid not null,operation_id uuid not null,request jsonb not null,primary key(tournament_id,roster_id),unique(tournament_id,actor_id,operation_id),foreign key(roster_id,tournament_id)references app.tournament_roster_entries(id,tournament_id));
do $$declare n text;begin foreach n in array array['operations','reviews']loop execute format('create trigger immutable before update or delete on identity_adoption_v8.%I for each row execute function identity_trial_v4.immutable()',n);execute format('create trigger no_truncate before truncate on identity_adoption_v8.%I for each statement execute function identity_trial_v4.immutable()',n);execute format('alter table identity_adoption_v8.%I enable row level security',n);execute format('alter table identity_adoption_v8.%I force row level security',n);end loop;end$$;
create function identity_adoption_v8.lock_scope(actor uuid,sid uuid,tid uuid,create_head boolean default false)returns void language plpgsql security invoker set search_path='' as $$begin
if not identity_trial_v4.authorized(actor,sid,tid)then raise exception'identity_access_changed';end if;
perform 1 from auth.sessions where id=sid and user_id=actor for share;
perform 1 from app.tournament_roles where tournament_id=tid and profile_id=actor and role='director' for share;
perform 1 from app.tournaments where id=tid for update;
if not found then raise exception'identity_scope_missing';end if;
lock table app.tournament_roster_entries,app.roster_account_links,app.event_participants,app.roster_entry_lifecycle_events in share mode;
if create_head then insert into identity_trial_v4.heads(tournament_id)values(tid)on conflict do nothing;end if;
perform 1 from identity_trial_v4.heads where tournament_id=tid for update;
lock table identity_trial_v4.issued,identity_trial_v4.issued_retired in share row exclusive mode;
if not identity_trial_v4.authorized(actor,sid,tid)then raise exception'identity_access_changed';end if;
end$$;
create function identity_adoption_v8.row_safe(tid uuid,rid uuid)returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from identity_legacy_v1.adoptions a where a.tournament_id=tid and a.roster_id=rid and a.source_digest=identity_legacy_v1.digest(tid,rid))$$;
create function identity_adoption_v8.inventory_digest(tid uuid)returns text language sql stable security invoker set search_path='' as $$select encode(sha256(convert_to(jsonb_build_object('legacy',coalesce((select jsonb_agg(identity_legacy_v1.source(tid,r.id)order by r.id)from app.tournament_roster_entries r where r.tournament_id=tid),'[]'),'facts',coalesce((select jsonb_agg(to_jsonb(f)order by f.roster_id)from identity_trial_v4.latest(tid)f),'[]'))::text,'UTF8')),'hex')$$;
create function identity_adoption_v8.inventory(actor uuid,sid uuid,tid uuid)returns jsonb language plpgsql security invoker set search_path='' as $$declare rows jsonb;begin
perform identity_adoption_v8.lock_scope(actor,sid,tid);
select coalesce(jsonb_agg(jsonb_build_object('rosterEntryId',r.id,'firstName',r.claimed_first_name,'lastName',r.claimed_last_name,'displayName',coalesce(f.display_name,r.claimed_display_name),'email',coalesce(r.claimed_email,''),'suppliedReference',coalesce(r.claimed_acc_number,''),'sourceDigest',identity_legacy_v1.digest(tid,r.id),'coverage','missing_legacy_address','scorecardType',r.scorecard_type,'status',case when a.roster_id is not null then case when identity_adoption_v8.row_safe(tid,r.id)then'adopted'else'binding_review_required'end when exists(select 1 from app.roster_account_links l where l.tournament_id=tid and l.roster_entry_id=r.id)or exists(select 1 from app.event_participants p where p.tournament_id=tid and p.roster_entry_id=r.id and p.profile_id is not null)then'account_identity_review_required'when coalesce((select e.event_type from app.roster_entry_lifecycle_events e where e.tournament_id=tid and e.roster_entry_id=r.id order by e.version desc limit 1),'active')='withdrawn'then'withdrawn'when r.claimed_first_name is null or r.claimed_last_name is null then'legal_name_review_required'when r.scorecard_type<>'paper'then'digital_identity_review_required'else'review_required'end)order by r.id),'[]')into rows from app.tournament_roster_entries r left join identity_legacy_v1.adoptions a on a.tournament_id=tid and a.roster_id=r.id left join identity_trial_v4.latest(tid)f on f.roster_id=r.id where r.tournament_id=tid;
return jsonb_build_object('kind','legacy-adoption-inventory-v8','actorId',actor,'sessionId',sid,'tournamentId',tid,'revision',coalesce((select revision from identity_trial_v4.heads where tournament_id=tid),0),'inventoryDigest',identity_adoption_v8.inventory_digest(tid),'rows',rows,'identityCandidates',coalesce((select jsonb_agg(jsonb_build_object('rosterEntryId',f.roster_id,'firstName',f.entry->>'firstName','lastName',f.entry->>'lastName','displayName',f.display_name)order by f.roster_id)from identity_trial_v4.latest(tid)f where not exists(select 1 from app.tournament_roster_entries r where r.tournament_id=tid and r.id=f.roster_id)),'[]'));end$$;
create function identity_adoption_v8.profile(actor uuid,sid uuid,tid uuid,rid uuid)returns jsonb language plpgsql security invoker set search_path='' as $$declare p jsonb;c text;begin
perform identity_adoption_v8.lock_scope(actor,sid,tid);if exists(select 1 from app.tournament_roster_entries where tournament_id=tid and id=rid)and not identity_adoption_v8.row_safe(tid,rid)then return null;end if;
p:=identity_trial_v4.read_player(actor,sid,tid,rid);if p is null then return null;end if;select coverage into c from identity_adoption_v8.reviews where tournament_id=tid and roster_id=rid;
return jsonb_build_object('kind','legacy-adoption-profile-v8','actorId',actor,'sessionId',sid,'tournamentId',tid,'rosterEntryId',rid,'coverage',coalesce(c,'complete'),'player',p);end$$;
commit;
